class Solution:
    def constructArray(self, n: int, k: int) -> list[int]:
        result = []
        low, high = 1, k + 1
        while low <= high:
            result.append(low)
            low += 1
            if low <= high:
                result.append(high)
                high -= 1
        result.extend(range(k + 2, n + 1))
        return result
